    logic [10:0]       rq_base;   // first st_rq.hex word
    logic [9:0]        lo, hi;    // clamp, two's complement
  } st_layer_t;

  typedef struct packed {
    logic [5:0]        in_point;  // ST_PT_NONE: pre reads the ISP slot
    logic [5:0]        aux_point; // ST_PT_NONE: no aux read
    logic [4:0]        out_point;
    logic              upsample;  // 2x nearest on the main input
    logic [1:0]        add_mode;  // ST_ADD_*
    logic [10:0]       add_rq;    // requant word of the add factor
    logic [4:0]        first_layer, n_layers;
    logic [11:0]        in_w, in_h;   // the ISP slot is 1280 wide
    logic [6:0]        in_c;
    logic [11:0]        out_w, out_h;
    logic [6:0]        out_c;
  } st_pass_t;

  typedef struct packed {
    logic [31:0]       base;      // DDR byte address, 4 KiB aligned
    logic [9:0]        w, h;
    logic [6:0]        c;
    logic [1:0]        elem;      // bytes per element: 1, or 2 on WIDE_POINTS
    logic [7:0]        pb;        // pixel bytes, roundup16(c * elem)
  } st_region_t;

  typedef struct packed {
    logic [23:0]       mant;      // factor = mant * 2**(-k)
